// === Tab: mySketch.js ===
/*
It is a 3D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Upside-down".

The reflections are axisymmetric, which is why you can also
view the scene upside down. Just give it a try: hold down the
left mouse button and drag down or up.
*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader, moves=[0,0];

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return
	moves[0] += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * scale
	moves[1] += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * scale
}

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2818760/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function draw() {
	mouseMove()
	shader(theShader)
	theShader.setUniform("resolution", [width * scale, height * scale])
	theShader.setUniform("time", millis() / 1000.0)
	theShader.setUniform("move", moves)
	theShader.setUniform("pointerCount", ((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) ? 1 : 0)
	rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 move;
uniform int pointerCount;
#define P pointerCount
#define FC gl_FragCoord.xy
#define R resolution
#define T time
#define N normalize
#define S smoothstep
#define MN min(R.x,R.y)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin(3.14*(a)+vec3(1,2,3)))
float smin(float a, float b, float k) {
	float h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
vec3 smin(vec3 a, vec3 b, float k) {
	vec3 h=clamp(.5+.5*(b-a)/k,.0,1.);
	return mix(b,a,h)-k*h*(1.-h);
}
float plane(vec3 p, vec3 n, float h) {
	return dot(p,n)+h;
}
float oct(vec3 p, float s, float k) {
	p=smin(p,-p,-s*k);
	return (p.x+p.y+p.z-s)*(1./sqrt(3.));
}
float gem(vec3 p, float s) {
	float k=.02, a=oct(p,s,k);
	p.xz*=rot(.78);
	return smin(smin(a,oct(p,s,k),s*k),-(-p.y+.1),-s*k);
}
float obj;
float map(vec3 p) {
	vec3 q=p;
	q.xz-=S(.5,1.,abs(p.y))*(.001*cos(48.*atan(p.x,p.z))-.001*sin(128.*p.y));
	float
	o=min(abs(length(q)-.9465)-.035,gem(p,.8)),
	d=min(o,plane(p,vec3(0,1,0),1.)),
	a=-plane(p,N(vec3(1,0,-1)),-12.),
	b=-plane(p,N(vec3(-1,0,-1)),-12.);
	d=min(d,min(a,b));
	obj=d<o?1.:.0;
	return d;
}
vec3 norm(vec3 p) {
	float h=1e-3; vec2 k=vec2(-1,1);
	return N(
		k.xyy*map(p+k.xyy*h)+
		k.yxy*map(p+k.yxy*h)+
		k.yyx*map(p+k.yyx*h)+
		k.xxx*map(p+k.xxx*h)
	);
}
vec3 dir(vec2 uv, vec3 p, vec3 t, float z) {
	vec3 up=vec3(0,1,0),
	f=N(t-p),
	r=N(cross(f,up)),
	u=N(cross(r,f));
	return N(mat3(r,u,f)*vec3(uv,z));
}
float effect(vec2 p) {
	p=abs(abs(p)-vec2(1.5,1))-vec2(1,2.75);
	float d=length(max(p,.0))+min(.0,max(p.x,p.y))-.02;
	return S(15./MN,.0,d);
}
void cam(inout vec3 p) {
	if (P>0) {
		p.yz*=rot(-sin(move.y*6.3/MN+1.57)*1.5+1.5);
		p.xz*=rot(-move.x*6.3/MN);
	} else {
		p.yz*=rot(exp(cos(T*.25)*.5-1.));
		p.xz*=rot(T*.2);
	}
}
void main() {
	vec2 uv=(FC-.5*R)/MN;
	vec3 col=vec3(0),
	p=vec3(0,0,-4),
	rd=dir(uv,p,vec3(0,.25,0),.8+(P>0?.0:.2*exp(-sin(T*.25)))),
	lp=vec3(1,2,5);
	cam(p); cam(rd);
	float dd=.0, at=.0, side=1., bnz=.0, lvl=.0, e=1.;
	for (float i=.0; i++<1400.;) {
		float d=map(p)*side;
		if (abs(d)<1e-3) {
			if (p.y>-1.+1e-3) {
				vec3 n=norm(p)*side, l=N(lp-p);
				if (dot(l,n)<.0) l=-l;
				vec3 r=reflect(rd, n),
				h=N(l-r);
				float dif=clamp(dot(l,n),.0,1.), fres=pow(clamp(1.+dot(rd,n),.0,1.),5.);
				vec3 mat=vec3(0);
				mat+=dif*fres*(
					.8*pow(max(.0,dot(h,n)),7.)+
					.2*pow(max(.0,dot(r,n)),2.)
				);
				mat+=5e-2*fres*vec3(1,.5,.5)*hue(length(p));
				mat+=5e-2*dif*vec3(1,.8,.05)*hue(length(p));
				col+=1e-3+mat*fres*15.;
				if (obj>.0) {
					vec3 pdd=p;
					pdd.xz*=rot(.78);
					col=mix(col,vec3(e),effect(vec2(1,.5)*vec3(plane(pdd,N(vec3(1,0,-1)),-6.)).xy));
					break;
				} else {
					fres=sqrt(1.-fres)*.5;
					vec3 rdd=reflect(n,rd);
					rdd.xz*=rot(1.57);
					col=max(col,-n.z*fres*effect(rdd.xy*vec2(12,4)*1.5));
					at+=.05*(.25/dd);
					col*=1.1;
				}
				side=-side;
				vec3 rdo=refract(rd,n,1.+side*.25);
				if (dot(rdo,rdo)==.0) rdo=reflect(rd,n);
				rd=rdo;
				d=1e-1;
				e*=.95;
			} else {
				vec3 n=vec3(0,1,0), l=N(lp-p);
				float dif=clamp(dot(l,n),.0,1.), spec=pow(clamp(dot(reflect(rd,n),l),.0,1.),32.),
				ld=max(distance(lp,p),1e-3);
				col+=e*.8*dif;
				col+=e*.5*spec;
				col*=1./(1.+ld*.5+ld*ld*.25);
				if (bnz++>0.) break;
				rd=reflect(rd,n);
				p+=n*1e-2;
				e*=.3;
			}
		}
		if (dd>20.) break;
		p+=rd*d;
		dd+=d;
		at+=.05*(.025/dd);
	}
	at*=5.;
	col+=at*at;
	col=S(-.1,1.,col);
	col=tanh(col*col*2.);
	col=pow(col,vec3(.4545));
	uv=2.*(FC/R)-1.;
	uv*=.6;
	col=mix(col,vec3(0),dot(uv,uv));
	col=max(col,.08);
	col=mix(vec3(0),col,min(1.,time*time*.3));
	O=vec4(col,1);
}

